# Find users who appear in both lists
def common_slow(a, b):
    return [x for x in a if x in b]       # 'in' on a list is O(len(b)) -> O(n*m)

def common_fast(a, b):
    b_set = set(b)                        # O(m) to build
    return [x for x in a if x in b_set]   # O(1) expected each -> O(n + m)

def lower_bound(a, target):
    # first index i where a[i] >= target; a must be sorted
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

from collections import deque

def shortest_hops(graph, start, goal):
    q = deque([(start, 0)])
    seen = {start}
    while q:
        node, d = q.popleft()
        if node == goal:
            return d
        for nxt in graph.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return -1

