// Minimal lit surface (HLSL). One vertex stage, one fragment stage.
cbuffer PerMaterial : register(b0)
{
    float4 _Tint;
    float  _Smoothness;
};
cbuffer PerFrame : register(b1)
{
    float4x4 _ViewProj;
    float3   _LightDir;   // direction toward the light, normalized
};
cbuffer PerObject : register(b2) { float4x4 _Model; };

Texture2D    _Albedo : register(t0);
SamplerState _Samp   : register(s0);

struct VSIn  { float3 pos : POSITION; float3 nrm : NORMAL; float2 uv : TEXCOORD0; };
struct VSOut { float4 clip : SV_Position; float3 nrmW : TEXCOORD1; float2 uv : TEXCOORD0; };

VSOut VS(VSIn i)
{
    VSOut o;
    float4 world = mul(_Model, float4(i.pos, 1.0));   // w = 1: a point
    o.clip = mul(_ViewProj, world);
    o.nrmW = mul((float3x3)_Model, i.nrm);            // assumes uniform scale
    o.uv   = i.uv;
    return o;
}

float4 PS(VSOut i) : SV_Target
{
    float3 n = normalize(i.nrmW);                      // re-normalize after interpolation
    float  ndl = saturate(dot(n, _LightDir));
    float3 albedo = _Albedo.Sample(_Samp, i.uv).rgb * _Tint.rgb;
    return float4(albedo * (0.1 + ndl), 1.0);
}

Texture2D    _Albedo;   // imported as sRGB: GPU converts to linear on Sample
Texture2D    _Normal;   // imported as linear data
SamplerState sampler_linear_repeat; // trilinear, 8x anisotropy, wrap

float4 Frag(float2 uv : TEXCOORD0) : SV_Target
{
    float3 albedo = _Albedo.Sample(sampler_linear_repeat, uv).rgb;  // already linear
    float3 n = _Normal.Sample(sampler_linear_repeat, uv).xyz * 2 - 1; // data, not colour
    return float4(albedo * Lighting(n), 1);
}

float3 BlinnPhong(float3 N, float3 L, float3 V, float3 albedo, float3 lightCol, float shininess)
{
    float3 H = normalize(L + V);
    float diff = saturate(dot(N, L));
    float spec = pow(saturate(dot(N, H)), shininess) * step(0.0, diff);
    return (albedo * diff + spec) * lightCol;
}

