// Sphere vs frustum: planes have normals pointing inward
bool InsideFrustum(const Sphere& s, const Plane planes[6]) {
    for (int i = 0; i < 6; ++i) {
        float dist = Dot(planes[i].normal, s.center) + planes[i].d;
        if (dist < -s.radius) return false; // fully outside this plane
    }
    return true; // inside or intersecting: render it
