// Semi-implicit Euler for one body, run at a fixed dt
void Integrate(ref Body b, float dt)
{
    b.velocity += (b.force * b.invMass + gravity) * dt;
    b.velocity *= 1f / (1f + b.linearDamping * dt);
    b.position += b.velocity * dt;
    b.force = Vector3.zero;
}

