// Pose blend with shortest-arc rotation
static void BlendPose(Pose a, Pose b, float w, Pose result)
{
    for (int i = 0; i < a.Count; i++)
    {
        result.pos[i] = Vector3.Lerp(a.pos[i], b.pos[i], w);
        Quaternion qb = b.rot[i];
        if (Quaternion.Dot(a.rot[i], qb) < 0f)
            qb = new Quaternion(-qb.x, -qb.y, -qb.z, -qb.w);
        result.rot[i] = Quaternion.Slerp(a.rot[i], qb, w);
    }
}

