public class FollowCamera : MonoBehaviour
{
    [SerializeField] Transform target;
    [SerializeField] float smoothTime = 0.15f;   // seconds, not frames
    [SerializeField] float lookAhead = 2.5f;     // metres in the movement direction
    [SerializeField] Vector2 deadZone = new Vector2(1.5f, 1f);
    Vector3 focus, velocity;

    void Start() => focus = target.position;

    void LateUpdate()
    {
        // Move the focus only when the target leaves the dead zone box.
        Vector3 d = target.position - focus;
        focus.x += Mathf.Sign(d.x) * Mathf.Max(0f, Mathf.Abs(d.x) - deadZone.x);
        focus.y += Mathf.Sign(d.y) * Mathf.Max(0f, Mathf.Abs(d.y) - deadZone.y);

        Vector3 goal = focus + Vector3.right * (lookAhead * facing);
        goal.z = transform.position.z;
        transform.position = Vector3.SmoothDamp(transform.position, goal, ref velocity, smoothTime);
    }

    public float facing = 1f; // +1 or -1, set by the player controller
}

public class CameraShake : MonoBehaviour   // on a child of the follow camera
{
    [SerializeField] float decayPerSecond = 1f, maxOffset = 0.4f, maxRoll = 3f, frequency = 18f;
    float trauma, seed;

    void Awake() => seed = Random.value * 1000f; // cosmetic, so the global stream is fine
    public void AddTrauma(float amount) => trauma = Mathf.Clamp01(trauma + amount);

    void LateUpdate()
    {
        trauma = Mathf.Max(0f, trauma - decayPerSecond * Time.unscaledDeltaTime);
        float shake = trauma * trauma;
        float t = Time.unscaledTime * frequency;
        float nx = Mathf.PerlinNoise(seed, t) * 2f - 1f;
        float ny = Mathf.PerlinNoise(seed + 1f, t) * 2f - 1f;
        float nr = Mathf.PerlinNoise(seed + 2f, t) * 2f - 1f;
        transform.localPosition = new Vector3(nx, ny, 0f) * (maxOffset * shake);
        transform.localRotation = Quaternion.Euler(0f, 0f, nr * maxRoll * shake);
    }
}

public sealed class Pool<T> where T : class
{
    readonly Stack<T> free = new Stack<T>();
    readonly Func<T> create;
    readonly Action<T> onGet, onRelease;

    public Pool(Func<T> create, Action<T> onGet, Action<T> onRelease, int warm)
    {
        this.create = create; this.onGet = onGet; this.onRelease = onRelease;
        for (int i = 0; i < warm; i++) free.Push(create());
    }
    public T Get()
    {
        T t = free.Count > 0 ? free.Pop() : create();
        onGet(t);
        return t;
    }
    public void Release(T t) { onRelease(t); free.Push(t); }
}

