// Unity 6 URP: a fullscreen tint pass (check signatures against your URP version)
class TintPass : ScriptableRenderPass
{
    class PassData { public TextureHandle src; public Material mat; }
    readonly Material mat;
    public TintPass(Material m) { mat = m; renderPassEvent = RenderPassEvent.BeforeRenderingPostProcessing; }

    public override void RecordRenderGraph(RenderGraph graph, ContextContainer frameData)
    {
        var res = frameData.Get<UniversalResourceData>();
        if (res.isActiveTargetBackBuffer) return;
        TextureHandle src = res.activeColorTexture;
        var desc = graph.GetTextureDesc(src);
        desc.name = "_TintTarget"; desc.clearBuffer = false;
        TextureHandle dst = graph.CreateTexture(desc);

        using var builder = graph.AddRasterRenderPass<PassData>("Tint", out var data);
        data.src = src; data.mat = mat;
        builder.UseTexture(src);                 // declared read
        builder.SetRenderAttachment(dst, 0);     // declared write
        builder.SetRenderFunc((PassData d, RasterGraphContext ctx) =>
            Blitter.BlitTexture(ctx.cmd, d.src, new Vector4(1, 1, 0, 0), d.mat, 0));
        res.cameraColor = dst;                    // later passes read the tinted result
    }
}

