// ArtBudgets is project code: a ScriptableObject the art lead edits,
// mapping folders (Characters, Props, Background) to budget numbers.
class ArtBudgetPostprocessor : AssetPostprocessor
{
    // Bump when the rules change so Unity reimports affected assets.
    public override uint GetVersion() => 3;

    void OnPreprocessTexture()
    {
        if (!assetPath.StartsWith("Assets/Art/")) return;
        var ti = (TextureImporter)assetImporter;
        var budget = ArtBudgets.ForPath(assetPath);

        // Fix what can be fixed silently: clamp size, linear masks.
        ti.maxTextureSize = Mathf.Min(ti.maxTextureSize, budget.maxTextureSize);
        if (assetPath.EndsWith("_M.png")) ti.sRGBTexture = false;

        ti.SetPlatformTextureSettings(new TextureImporterPlatformSettings
        {
            name = "Android",
            overridden = true,
            maxTextureSize = budget.maxTextureSize,
            format = TextureImporterFormat.ASTC_6x6
        });
    }

    void OnPostprocessModel(GameObject root)
    {
        if (!assetPath.StartsWith("Assets/Art/")) return;
        var budget = ArtBudgets.ForPath(assetPath);

        // Report what cannot be fixed: the mesh itself is over budget.
        // (A real rule checks each LOD level against its own number.)
        int tris = 0;
        foreach (var mf in root.GetComponentsInChildren<MeshFilter>(true))
            tris += Triangles(mf.sharedMesh);
        foreach (var smr in root.GetComponentsInChildren<SkinnedMeshRenderer>(true))
            tris += Triangles(smr.sharedMesh);

        if (tris > budget.maxTriangles)
            context.LogImportError(
                $"{assetPath}: {tris} triangles, budget is {budget.maxTriangles}");
    }

    static int Triangles(Mesh m)
    {
        if (m == null) return 0;
        long indices = 0;
        for (int i = 0; i < m.subMeshCount; i++) indices += m.GetIndexCount(i);
        return (int)(indices / 3);
    }
}

