public sealed class Position            // plain C#, no UnityEngine types
{
    public ulong[] Pieces = new ulong[12];  // [color * 6 + type], one bit per square
    public ulong Occupied;                  // cached union of all twelve
    public bool WhiteToMove;
    public byte Castling;                   // bit0 K, bit1 Q, bit2 k, bit3 q
    public sbyte EpSquare = -1;             // -1 when no en passant capture is possible
    public ushort Halfmove, Fullmove;
    public ulong Hash;                      // Zobrist key, updated incrementally
}

// history[count - 1] is the current position's hash.
static bool IsRepetition(ulong[] history, int count, int halfmove)
{
    // Same side to move means every second ply; stop at the last irreversible move.
    for (int i = count - 3; i >= count - 1 - halfmove && i >= 0; i -= 2)
        if (history[i] == history[count - 1]) return true;
    return false;
}

static readonly ulong[] KnightAttacks = new ulong[64];

static void InitKnights()
{
    int[] df = { 1, 2, 2, 1, -1, -2, -2, -1 };
    int[] dr = { 2, 1, -1, -2, -2, -1, 1, 2 };
    for (int sq = 0; sq < 64; sq++)
        for (int i = 0; i < 8; i++)
        {
            int f = (sq & 7) + df[i], r = (sq >> 3) + dr[i];
            if (f >= 0 && f < 8 && r >= 0 && r < 8)
                KnightAttacks[sq] |= 1UL << (r * 8 + f);
        }
}

// Sliders: keep only relevant blockers, multiply by the magic, shift, look up.
static ulong RookAttacks(int sq, ulong occ)
{
    ulong blockers = occ & RookMask[sq];
    int index = (int)((blockers * RookMagic[sq]) >> RookShift[sq]);
    return RookTable[sq][index];
}

static long Perft(Position p, int depth)
{
    if (depth == 0) return 1;
    long nodes = 0;
    foreach (Move m in MoveGen.PseudoLegal(p))
    {
        Position next = p.Apply(m);              // copy-make
        if (next.IsKingAttacked(!next.WhiteToMove)) continue;   // mover's own king in check
        nodes += Perft(next, depth - 1);
    }
    return nodes;
}

int Search(Position p, int depth, int alpha, int beta, int ply)
{
    if (ply > 0 && IsDraw(p)) return 0;           // repetition or 50-move rule
    if (depth <= 0) return Quiesce(p, alpha, beta);
    int alphaStart = alpha;
    Move ttMove = default;
    if (tt.Probe(p.Hash, out Entry e))
    {
        ttMove = e.Move;
        if (e.Depth >= depth && ProvesCutoff(e, alpha, beta)) return e.Score;
    }
    int best = -Mate, legal = 0; Move bestMove = default;
    foreach (Move m in OrderedMoves(p, ttMove, ply))
    {
        Position next = p.Apply(m);
        if (next.IsKingAttacked(!next.WhiteToMove)) continue;   // pseudo-legal filter
        legal++;
        int score = -Search(next, depth - 1, -beta, -alpha, ply + 1);
        if (score > best) { best = score; bestMove = m; }
        if (score > alpha) alpha = score;
        if (alpha >= beta) { RecordKillerAndHistory(m, depth, ply); break; }   // beta cutoff
    }
    if (legal == 0) return p.InCheck() ? -Mate + ply : 0;       // mated or stalemate
    tt.Store(p.Hash, depth, best, bestMove, best <= alphaStart ? Bound.Upper : best >= beta ? Bound.Lower : Bound.Exact);
    return best;
}

static readonly ulong[,] PieceKey = new ulong[12, 64];   // filled once from a seeded PRNG
static readonly ulong SideKey;
static readonly ulong[] CastleKey = new ulong[16], EpFileKey = new ulong[8];

// Inside Apply(move), for an ordinary capture or quiet move:
ulong h = pos.Hash;
h ^= PieceKey[piece, from];                   // lift the piece off
h ^= PieceKey[piece, to];                     // put it down
if (captured >= 0) h ^= PieceKey[captured, to];
h ^= CastleKey[oldCastling] ^ CastleKey[newCastling];
if (oldEp >= 0) h ^= EpFileKey[oldEp & 7];
if (newEp >= 0) h ^= EpFileKey[newEp & 7];
h ^= SideKey;                                 // flip the side to move
// En passant, castling and promotion add their extra XORs the same way.

int Evaluate(Position p)
{
    int mg = 0, eg = 0, phase = 0;
    foreach (var (piece, sq) in p.AllPieces())        // iterates set bits of each bitboard
    {
        int t = piece.Type, s = piece.IsWhite ? 1 : -1;
        int i = Oriented(sq, piece);                  // mirror the table for black
        mg += s * (MgValue[t] + MgTable[t][i]);
        eg += s * (EgValue[t] + EgTable[t][i]);
        phase += PhaseWeight[t];                      // N,B = 1; R = 2; Q = 4; P,K = 0
    }
    phase = Math.Min(phase, 24);
    int score = (mg * phase + eg * (24 - phase)) / 24;    // white's view
    return p.WhiteToMove ? score : -score;                // side to move's view
}

