void ApplyWheel(Wheel w, float dt)
{
    if (!Physics.Raycast(w.mount, -transform.up, out var hit, w.rest + w.radius)) return;
    float compression = w.rest - (hit.distance - w.radius);
    float compSpeed = (compression - w.lastCompression) / dt;
    w.lastCompression = compression;
    float spring = Mathf.Max(0f, k * compression - c * compSpeed);
    rb.AddForceAtPosition(hit.normal * spring, hit.point);

    // Lateral grip: cancel a fraction of sideways speed at this wheel.
    Vector3 v = rb.GetPointVelocity(hit.point);
    float side = Vector3.Dot(v, w.transform.right);
    float impulse = -side * w.grip * (rb.mass * 0.25f);
    rb.AddForceAtPosition(w.transform.right * impulse / dt, hit.point);
}

void TickDrift(float dt, bool held, float steer)
{
    if (held && speed > 10f) {
