        tier = driftTime >= 2.5f ? 3 : driftTime >= 1.5f ? 2 : driftTime >= 0.7f ? 1 : 0;
        rearGrip = 0.6f;
    } else {
        if (driftTime > 0f && tier > 0) boostLeft = BoostSeconds[tier - 1]; // 0.6, 1.0, 1.5
        driftTime = 0f; tier = 0; rearGrip = 1f;
    }
    boostLeft = Mathf.Max(0f, boostLeft - dt);
    maxSpeed = boostLeft > 0f ? baseMax * 1.3f : baseMax;
}

int FindIndex(Vector3 p, int last)
{
    int best = last; float bestD = float.MaxValue;
    for (int o = -30; o <= 30; o++) {
        int i = (last + o + n) % n;
        float d = (pts[i] - p).sqrMagnitude;
        if (d < bestD) { bestD = d; best = i; }
    }
    // Seam wrap keeps progress continuous. The official lap count comes from the gates.
    if (last > n - 40 && best < 40) progressLap++;
    else if (last < 40 && best > n - 40) progressLap--;
