void OnServerState(int tick, KartState s)
{
    // Discard acknowledged inputs, then rewind to the authoritative state.
    while (pending.Count > 0 && pending.Peek().tick <= tick) pending.Dequeue();
    Vector3 shownPos = kart.Position + visualError;   // what the player sees now
    kart.Restore(s);
    foreach (var input in pending)          // 601..605 in the example
        kart.Step(input, fixedDt);
    // Show the corrected state smoothly: error decays instead of snapping.
    visualError = shownPos - kart.Position;
}
void LateUpdate()
{
