    visual.position = kart.Position + visualError;
}

// Quake-style acceleration. Same code and same dt on client and server.
Vector3 Accelerate(Vector3 vel, Vector3 wishDir, float wishSpeed, float accel, float dt)
{
    float current = Vector3.Dot(vel, wishDir);   // speed already along wishDir
    float add = wishSpeed - current;             // room left in that direction
    if (add <= 0f) return vel;
    float gain = Mathf.Min(accel * wishSpeed * dt, add);
    return vel + wishDir * gain;
}

void GroundMove(ref Vector3 vel, Vector3 wishDir, float dt)
{
    float speed = vel.magnitude;
    if (speed > 0.01f)                           // friction first
    {
        float drop = Mathf.Max(speed, stopSpeed) * friction * dt;
        vel *= Mathf.Max(speed - drop, 0f) / speed;
    }
    vel = Accelerate(vel, wishDir, maxSpeed, groundAccel, dt);
}

