// Server-side fire. Cooldown accumulates; it never resets to 'now'.
void Fire(Player p, WeaponDef w, float now)
{
    if (now < p.nextFire) return;
    // At most one tick of slack, so idle time cannot bank extra shots.
    p.nextFire = Mathf.Max(p.nextFire, now - tickDt) + 60f / w.rpm;
    Vector3 dir = ApplyRecoilAndSpread(p, w);       // seeded by shot index + tick

    lagComp.Rewind(p.viewTime);                      // hitboxes as the shooter saw them
    if (Physics.Raycast(p.eye, dir, out var hit, w.maxRange, hitMask))
        if (hit.collider.TryGetComponent(out Hitbox hb))
            hb.owner.ApplyDamage(
                w.damage * w.falloff.Evaluate(hit.distance) * hb.multiplier, p);
    lagComp.Restore();
}

void OnSnapshot(Snapshot s)
{
    pending.DiscardUpTo(s.lastProcessedCmd);       // server has seen these
    PlayerState state = s.localState;              // authoritative at that tick
    foreach (var cmd in pending)                   // replay the rest on top
        state = Movement.Step(state, cmd, tickDt);

    float err = Vector3.Distance(predicted.pos, state.pos);
    if (err > 1.0f)       renderOffset = Vector3.zero;                 // large: snap
    else if (err > 0.01f) renderOffset += predicted.pos - state.pos;   // small: smooth
    predicted = state;                                                  // offset decays per frame
}

