enum Stage { Additive = 0, Multiplicative = 1 }
struct Modifier { public Stage Stage; public float Value; public int SourceId; }

public float Get()
{
    if (!dirty) return cached;
    float add = 0f, mul = 1f;
    foreach (var m in modifiers)                 // kept sorted by (Stage, SourceId)
        if (m.Stage == Stage.Additive) add += m.Value; else mul *= m.Value;
    cached = Mathf.Clamp((baseValue + add) * mul, min, max);
    dirty = false;
    return cached;
}
public void Remove(int sourceId) { modifiers.RemoveAll(m => m.SourceId == sourceId); dirty = true; }

struct Condition { public string Fact; public Op Op; public int Value; }

bool Passes(Condition c, Facts f)
{
    int v = f.Get(c.Fact);                       // a missing fact reads as 0
    switch (c.Op)
    {
        case Op.Eq: return v == c.Value;
        case Op.Ge: return v >= c.Value;
        case Op.Lt: return v <  c.Value;
        default:    return v != c.Value;
    }
}

