void Tick() {                                         // once per 16.7 ms
    net.Poll();                                       // receive remote inputs
    inputs.SetLocal(frame + inputDelay, pad.Sample());
    if (frame - net.ConfirmedFrame > MaxRollback) return;   // stall, wait for the peer

    int bad = inputs.FirstMispredicted();             // -1 if every guess was right
    if (bad >= 0) {
        state = ring[bad % Ring];                     // state before frame 'bad'
        for (int f = bad; f < frame; f++) {
            ring[f % Ring] = state;                   // re-save as we go
            Sim.Step(ref state, inputs.Get(f, 0), inputs.Get(f, 1)); // real or predicted
        }
    }
    ring[frame % Ring] = state;
    Sim.Step(ref state, inputs.Get(frame, 0), inputs.Get(frame, 1));
    frame++;
    Render(state);                                    // draw once per tick, never mid-resim
}

